  // noticeTick removed — countdown display is no longer shown on student notice board

  const calculateExpiry = (timerOption: any, customExpiresAt: any) => {
    if (!timerOption || timerOption === "none") return null;
    const now = new Date();
    if (timerOption === "24h") {
      return new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString();
    }
    if (timerOption === "3d") {
      return new Date(now.getTime() + 3 * 24 * 60 * 60 * 1000).toISOString();
    }
    if (timerOption === "7d") {
      return new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000).toISOString();
    }
    if (timerOption === "10d") {
      return new Date(now.getTime() + 10 * 24 * 60 * 60 * 1000).toISOString();
    }
    if (timerOption === "15d") {
      return new Date(now.getTime() + 15 * 24 * 60 * 60 * 1000).toISOString();
    }
    if (timerOption === "20d") {
      return new Date(now.getTime() + 20 * 24 * 60 * 60 * 1000).toISOString();
    }
    if (timerOption === "30d") {
      return new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000).toISOString();
    }
    if (timerOption === "custom" && customExpiresAt) {
      const parsed = new Date(customExpiresAt.replace(" ", "T"));
      if (!isNaN(parsed.getTime())) {
        return parsed.toISOString();
      }
    }
    return null;
  };

  const formatCountdown = (expiresAtStr: any) => {
    if (!expiresAtStr) return null;
    const expiry = new Date(expiresAtStr).getTime();
    const diff = expiry - Date.now();
    if (diff <= 0) return "Expired";
    
    const seconds = Math.floor((diff / 1000) % 60);
    const minutes = Math.floor((diff / (1000 * 60)) % 60);
    const hours = Math.floor((diff / (1000 * 60 * 60)) % 24);
    const days = Math.floor(diff / (1000 * 60 * 60 * 24));
    
    let parts = [];
    if (days > 0) parts.push(days + "d");
    if (hours > 0 || days > 0) parts.push(hours + "h");
    if (minutes > 0 || hours > 0 || days > 0) parts.push(minutes + "m");
    parts.push(seconds + "s");
    
    return parts.join(" ");
  };
