  const getBaseUrl = () => {
    if (Platform.OS === "web" && typeof window !== "undefined" && window.location && window.location.hostname) {
      const hostname = window.location.hostname;
      if (hostname === "localhost" || hostname === "127.0.0.1" || hostname.startsWith("192.168.") || hostname.startsWith("10.") || hostname.startsWith("172.")) {
        return `http://${hostname}:5000/api`;
      }
      return `https://${hostname}/api`;
    }
    return `http://${hostIpRef.current || DEFAULT_HOST_IP}:5000/api`;
  };
  const extractionAbortRef = useRef<AbortController | null>(null);
  // Auth token ref — always holds the latest JWT so api methods can inject without stale closures
  const tokenRef = useRef<string | null>(null);
  // User ref to avoid stale closures in api methods
  const userRef = useRef<any>(null);

  const api = useRef({
    getAuthHeaders(): Record<string, string> {
      const t = tokenRef.current;
      const u = userRef.current;
      const headers: Record<string, string> = {};
      if (t) headers.Authorization = `Bearer ${t}`;
      if (u?.role) headers["user-role"] = u.role;
      return headers;
    },
     handleResponse(res: Response, data: any) {
      if (res.status === 202 && data && data.approvalRequired) {
        Alert.alert("Submitted for Approval", data.message || "Your change proposal has been submitted to Super Admin for review.");
        return data;
      }
      if (!res.ok) {
        if (res.status === 401 && (data.message === "Session revoked" || String(data.message).toLowerCase().includes("session revoked"))) {
          performLogout();
          showToast("Logged out: Your ID was logged in on a new device.", "error");
        }
        throw new Error(data.message || `HTTP ${res.status}`);
      }
      return data.data !== undefined ? data.data : data;
    },
    async get(path: string, headers?: any) {
      const baseUrl = getBaseUrl();
      const controller = new AbortController();
      const id = setTimeout(() => controller.abort(), API_TIMEOUT_MS);
      try {
        const res = await fetch(`${baseUrl}${path}`, {
          headers: { "Content-Type": "application/json", ...this.getAuthHeaders(), ...headers },
          signal: controller.signal
        });
        clearTimeout(id);
        const data = await res.json();
        return this.handleResponse(res, data);
      } catch (e: any) {
        clearTimeout(id);
        if (e.name === "AbortError" || e.message === "aborted" || String(e.message).toLowerCase().includes("aborted")) {
          throw new Error("Request timed out. Please check your connection and try again.");
        }
        throw e;
      }
    },
    async post(path: string, body: any, headers?: any, customTimeout?: number) {
      const baseUrl = getBaseUrl();
      const controller = new AbortController();
      const id = setTimeout(() => controller.abort(), customTimeout || API_TIMEOUT_MS);
      try {
        const res = await fetch(`${baseUrl}${path}`, {
          method: "POST",
          headers: { "Content-Type": "application/json", ...this.getAuthHeaders(), ...headers },
          body: JSON.stringify(body),
          signal: controller.signal
        });
        clearTimeout(id);
        const data = await res.json();
        return this.handleResponse(res, data);
      } catch (e: any) {
        clearTimeout(id);
        if (e.name === "AbortError" || e.message === "aborted" || String(e.message).toLowerCase().includes("aborted")) {
          throw new Error("Request timed out while uploading. Please check your connection or try smaller images.");
        }
        throw e;
      }
    },
    async put(path: string, body: any, headers?: any, customTimeout?: number) {
      const baseUrl = getBaseUrl();
      const controller = new AbortController();
      const id = setTimeout(() => controller.abort(), customTimeout || API_TIMEOUT_MS);
      try {
        const res = await fetch(`${baseUrl}${path}`, {
          method: "PUT",
          headers: { "Content-Type": "application/json", ...this.getAuthHeaders(), ...headers },
          body: JSON.stringify(body),
          signal: controller.signal
        });
        clearTimeout(id);
        const data = await res.json();
        return this.handleResponse(res, data);
      } catch (e: any) {
        clearTimeout(id);
        if (e.name === "AbortError" || e.message === "aborted" || String(e.message).toLowerCase().includes("aborted")) {
          throw new Error("Request timed out. Please check your connection and try again.");
        }
        throw e;
      }
    },
    async patch(path: string, body: any, headers?: any) {
      const baseUrl = getBaseUrl();
      const controller = new AbortController();
      const id = setTimeout(() => controller.abort(), API_TIMEOUT_MS);
      try {
        const res = await fetch(`${baseUrl}${path}`, {
          method: "PATCH",
          headers: { "Content-Type": "application/json", ...this.getAuthHeaders(), ...headers },
          body: JSON.stringify(body),
          signal: controller.signal
        });
        clearTimeout(id);
        const data = await res.json();
        return this.handleResponse(res, data);
      } catch (e: any) {
        clearTimeout(id);
        if (e.name === "AbortError" || e.message === "aborted" || String(e.message).toLowerCase().includes("aborted")) {
          throw new Error("Request timed out. Please check your connection and try again.");
        }
        throw e;
      }
    },
    async delete(path: string, headers?: any) {
      const baseUrl = getBaseUrl();
      const controller = new AbortController();
      const id = setTimeout(() => controller.abort(), API_TIMEOUT_MS);
      try {
        const res = await fetch(`${baseUrl}${path}`, {
          method: "DELETE",
          headers: { "Content-Type": "application/json", ...this.getAuthHeaders(), ...headers },
          signal: controller.signal
        });
        clearTimeout(id);
        const data = await res.json();
        return this.handleResponse(res, data);
      } catch (e: any) {
        clearTimeout(id);
        if (e.name === "AbortError" || e.message === "aborted" || String(e.message).toLowerCase().includes("aborted")) {
          throw new Error("Request timed out. Please check your connection and try again.");
        }
        throw e;
      }
    }
  }).current;

