  const consumeOneTimePermission = async (featureKey: string) => {
    try {
      await api.post("/developer/consume-one-time-permission", { feature: featureKey });
      loadOneTimePermissions();
    } catch (e) {
      console.log("Failed to consume one time permission:", e);
    }
  };

  const getFeatureAccess = (featureKey: string): "none" | "view" | "edit_direct" | "edit_on_approval" => {
    if (!user) return "none";
    if (user.role === "developer" || user.role === "super_admin") return "edit_direct";
    if (user.role === "student" || user.role === "guest") return "edit_direct";
    
    // Check JIT (One-Time Upload) Permission
    if ((oneTimePermissions[featureKey] || 0) > 0) {
      return "edit_direct";
    }

    const rawCustom = user.customPermissions?.[featureKey];
    if (rawCustom) {
      if (rawCustom === "none") return "none";
      if (rawCustom === "view" || rawCustom === "CRU only" || rawCustom === "CR only" || rawCustom === "U only") return "view";
      if (rawCustom === "edit_direct" || rawCustom === "CRUD") return "edit_direct";
      return "edit_on_approval";
    }
    const rawRole = rolePermissions?.[user.role]?.[featureKey];
    if (rawRole) {
      if (rawRole === "none") return "none";
      if (rawRole === "view" || rawRole === "CRU only" || rawRole === "CR only" || rawRole === "U only") return "view";
      if (rawRole === "edit_direct" || rawRole === "CRUD") return "edit_direct";
      return "edit_on_approval";
    }
    // Default: no permission configured = no access (security-first approach)
    // Super admin / developer are already handled above and always get edit_direct
    return "none";
  };

  const canEditDaily = isAdmin && (
    user?.role === "super_admin" ||
    user?.role === "developer" ||
    getFeatureAccess("lms_daily_content") === "edit_direct" ||
    getFeatureAccess("lms_daily_content") === "edit_on_approval"
  );

  const executeEditOrApproval = (
    featureKey: string,
    actionType: "create" | "edit" | "delete",
    proposedPayload: any,
    directCallback: () => Promise<void> | void,
    targetCollection?: string,
    docId?: string
  ) => {
    const hasOneTime = (oneTimePermissions[featureKey] || 0) > 0;
    const access = hasOneTime ? "edit_direct" : getFeatureAccess(featureKey);

    if (access === "none") {
      Alert.alert("Permission Denied", "You do not have permission to perform actions in this section.");
      return;
    }
    if (access === "view") {
      Alert.alert("Read-Only Access", "Your admin permissions for this feature are set to View Only.");
      return;
    }
    if (access === "edit_direct") {
      const res = directCallback();
      if (hasOneTime) {
        if (res instanceof Promise) {
          res.then(() => consumeOneTimePermission(featureKey)).catch(() => {});
        } else {
          consumeOneTimePermission(featureKey);
        }
      }
      return;
    }
    if (access === "edit_on_approval") {
      confirmAction(
        "Super Admin Approval Required",
        `Your admin account requires Super Admin approval to ${actionType} items in this section. Submit proposal for Super Admin review?`,
        async () => {
          // Mark feature as submitting — shows loading spinner on buttons
          setSubmittingFeatures(prev => {
            const next = new Set(prev);
            next.add(featureKey);
            return next;
          });
          try {
            // The API call hits the real route (e.g., PUT /erp/student/:id)
            // The requirePermission middleware intercepts it (edit_on_approval)
            // and routes to AdminApprovalService.submitRequest() returning 202 + requestId
            const res = await directCallback();
            const responseData = (res as any)?.data || res;
            const requestId = responseData?.requestId;

            // Add to pending submissions list so UI shows pending badge
            setPendingSubmissions(prev => [...prev.filter(k => k !== featureKey), featureKey]);
            loadPendingApprovals();
            Alert.alert(
              "✅ Submitted for Approval",
              `Your ${actionType} request has been submitted. The page will update once the Super Admin approves it.`
            );
          } catch (e: any) {
            // 202 responses can throw in some axios configs — treat as success
            if (e?.response?.status === 202 || e?.status === 202) {
              const requestId = e?.response?.data?.requestId;
              setPendingSubmissions(prev => [...prev.filter(k => k !== featureKey), featureKey]);
              loadPendingApprovals();
              Alert.alert(
                "✅ Submitted for Approval",
                `Your ${actionType} request has been submitted. The page will update once the Super Admin approves it.`
              );
            } else {
              Alert.alert("Error", e.message || "Failed to submit request.");
            }
          } finally {
            // Clear submitting state
            setSubmittingFeatures(prev => {
              const next = new Set(prev);
              next.delete(featureKey);
              return next;
            });
          }
        },
        "Submit Request",
        false
      );
    }
  };

  /** Returns true while an edit_on_approval request is being submitted for a feature */
  const isSubmittingApproval = (featureKey: string): boolean => submittingFeatures.has(featureKey);

  /** Returns true if a pending approval request exists for a feature (submitted but not yet approved) */
  const hasPendingApproval = (featureKey: string): boolean =>
    pendingSubmissions.includes(featureKey) ||
    pendingApprovals.some((p: any) => p.feature === featureKey && p.status === "pending");

