  // Guest Login Handler (email-only)
  const handleGuestLogin = async () => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!guestEmail.trim()) {
      Alert.alert("Required", "Please enter your email address.");
      return;
    }
    if (!emailRegex.test(guestEmail.trim())) {
      Alert.alert("Invalid Email", "Please enter a valid email address.");
      return;
    }
    try {
      const res = await api.post("/crm/leads/guest-login", {
        email: guestEmail.trim().toLowerCase()
      });
      const data = res.data || res;
      const guestUser = {
        role: "guest",
        name: data.name || guestEmail.split("@")[0],
        phone: data.phone || "",
        email: data.email || guestEmail.trim().toLowerCase(),
        leadId: data.leadId,
        hasApplied: data.hasApplied || false,
        userId: data.leadId,
        token: data.token,
        hallTicketGenerated: data.hallTicketGenerated || false,
        hallTicketExamName: data.hallTicketExamName || "",
        hallTicketExamDate: data.hallTicketExamDate || "",
        hallTicketVenue: data.hallTicketVenue || "",
        hallTicketTime: data.hallTicketTime || "",
        hallTicketInstructions: data.hallTicketInstructions || ""
      };
      setUser(guestUser);
      setGuestEmailUnlocked(true);
      setAdmissionSubmitted(data.hasApplied || false);
      setGuestTab("home");
      setShowLoginModal(false);
      loadAnnouncements();
      loadGuestNotifications(data.leadId, data.token);
      loadCampaigns();

      // Save email and full user session locally for 7-day auto-login
      await guestStorage.save(guestEmail.trim().toLowerCase());
      await userStorage.save(guestUser);
    } catch (e: any) {
      Alert.alert("Error", e.message || "Could not start guest session.");
    }
  };

