  // Document picker helper for mobile document selection
  const pickWordDocument = async (target: "qp" | "ak") => {
    try {
      const docTypes = target === "qp"
        ? [
          "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
          "application/msword"
        ]
        : [
          "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
          "application/msword",
          "text/csv",
          "text/comma-separated-values",
          "application/csv",
          "text/plain"
        ];

      const result = await DocumentPicker.getDocumentAsync({
        type: docTypes,
        copyToCacheDirectory: true,
      });

      if (!result.canceled && result.assets && result.assets.length > 0) {
        const asset = result.assets[0];
        if (target === "qp") {
          setPdfFilename(asset.name);
        } else {
          setAkFilename(asset.name);
        }

        // On native platforms we read file as base64 string
        const base64 = await FileSystem.readAsStringAsync(asset.uri, {
          encoding: "base64",
        });

        if (target === "qp") {
          setPdfBase64(base64);
        } else {
          setAkBase64(base64);
        }
        Alert.alert("Success", `${target === "qp" ? "Question Paper" : "Answer Key"}"${asset.name}"loaded successfully!`);
      }
    } catch (err: any) {
      Alert.alert("Error", "Failed to select document:" + err.message);
    }
  };

  // AI PDF Question Extraction (Admin)
  const parseAndLoadJsonQuestions = () => {
    if (!jsonQuestionsInput.trim()) {
      Alert.alert("Error", "Please paste the JSON questions array.");
      return;
    }
    try {
      const parsed = JSON.parse(jsonQuestionsInput);
      if (!Array.isArray(parsed)) {
        throw new Error("JSON must be an array of questions.");
      }
      const normalized = parsed.map((q: any) => {
        const questionEn = q.questionEn || q.questionText || q.question || "";
        const questionTa = q.questionTa || "";
        const questionMl = q.questionMl || "";
        const questionTe = q.questionTe || "";
        const formula = q.formula || "";
        const explanation = q.explanation || "";

        let optionsObj: any = {
          A: { en: "", ta: "", ml: "", te: "" },
          B: { en: "", ta: "", ml: "", te: "" },
          C: { en: "", ta: "", ml: "", te: "" },
          D: { en: "", ta: "", ml: "", te: "" }
        };
        if (q.options && typeof q.options === "object" && !Array.isArray(q.options)) {
          ["A", "B", "C", "D"].forEach(k => {
            optionsObj[k].en = q.options[k]?.en || q.options[k] || "";
            optionsObj[k].ta = q.options[k]?.ta || "";
            optionsObj[k].ml = q.options[k]?.ml || "";
            optionsObj[k].te = q.options[k]?.te || "";
          });
        } else if (Array.isArray(q.options)) {
          ["A", "B", "C", "D"].forEach((k, idx) => {
            optionsObj[k].en = q.options[idx] || "";
          });
        }
        ["A", "B", "C", "D"].forEach(k => {
          const lk = k.toLowerCase();
          const flatEn = q[`option ${lk}`] || q[`option${k}`] || "";
          const flatTa = q[`optionTa_${lk}`] || q[`optionTa_${k}`] || q[`option ${lk} ta`] || q[`option${k}Ta`] || "";
          const flatMl = q[`optionMl_${lk}`] || q[`optionMl_${k}`] || q[`option ${lk} ml`] || q[`option${k}Ml`] || "";
          const flatTe = q[`optionTe_${lk}`] || q[`optionTe_${k}`] || q[`option ${lk} te`] || q[`option${k}Te`] || "";
          if (flatEn && !optionsObj[k].en) optionsObj[k].en = flatEn;
          if (flatTa && !optionsObj[k].ta) optionsObj[k].ta = flatTa;
          if (flatMl && !optionsObj[k].ml) optionsObj[k].ml = flatMl;
          if (flatTe && !optionsObj[k].te) optionsObj[k].te = flatTe;
        });

        // Generate optionsTa, optionsMl, optionsTe lists for convenient access
        const optionsTa = ["A", "B", "C", "D"].map(k => optionsObj[k].ta).filter(Boolean);
        const optionsMl = ["A", "B", "C", "D"].map(k => optionsObj[k].ml).filter(Boolean);
        const optionsTe = ["A", "B", "C", "D"].map(k => optionsObj[k].te).filter(Boolean);

        let correctAnswer = q.correctAnswer || q.correctOption || q["correct option"] || q.answer || "";
        correctAnswer = correctAnswer.toString().trim().toUpperCase();
        if (!["A", "B", "C", "D"].includes(correctAnswer)) {
          correctAnswer = "A";
        }
        return {
          ...q,
          questionEn,
          questionTa,
          questionMl,
          questionTe,
          formula,
          explanation,
          options: optionsObj,
          optionsTa: optionsTa.length > 0 ? optionsTa : q.optionsTa,
          optionsMl: optionsMl.length > 0 ? optionsMl : q.optionsMl,
          optionsTe: optionsTe.length > 0 ? optionsTe : q.optionsTe,
          correctAnswer
        };
      });
      setExtractedQuestions(normalized);
      setExtractDraftId("json_parsed");
      Alert.alert("Success", `Successfully parsed and loaded ${normalized.length} questions into workspace!`);
    } catch (err: any) {
      Alert.alert("Invalid JSON", err.message || "Failed to parse JSON. Please check prompt instructions and try again.");
    }
  };

  const extractQuestionsFromText = async () => {
    if (genMode === "json") {
      parseAndLoadJsonQuestions();
      return;
    }
    if (genMode === "file" && !pdfBase64) {
      Alert.alert("Error", "Please upload a Question Paper Word File (.docx).");
      return;
    }
    if (genMode === "text" && !pdfExtractText.trim()) {
      Alert.alert("Error", "Please paste the Question Paper text.");
      return;
    }
    setIsExtracting(true);
    const abortCtrl = new AbortController();
    extractionAbortRef.current = abortCtrl;
    try {
      const res = await api.post("/test-portal/test-creation/extract", {
        questionPaperText: genMode === "text" ? pdfExtractText : undefined,
        questionPaperBase64: genMode === "file" ? pdfBase64 : undefined,
        answerKeyBase64: akBase64 || undefined,
        filename: genMode === "file" ? pdfFilename : "pasted_text.txt",
        title: newPdfTest.title || "Untitled Test",
        mode: extractMode
      }, undefined, 180000); // 3 minutes timeout for AI processing
      if (abortCtrl.signal.aborted) return;
      const data = res.data || res;
      const normalized = (data.questions || []).map((q: any) => {
        const questionEn = q.questionEn || q.questionText || q.question || "";
        const questionTa = q.questionTa || "";
        let optionsObj: any = {
          A: { en: "", ta: "" },
          B: { en: "", ta: "" },
          C: { en: "", ta: "" },
          D: { en: "", ta: "" }
        };
        if (q.options && typeof q.options === "object" && !Array.isArray(q.options)) {
          ["A", "B", "C", "D"].forEach(k => {
            optionsObj[k].en = q.options[k]?.en || q.options[k] || "";
            optionsObj[k].ta = q.options[k]?.ta || "";
          });
        } else if (Array.isArray(q.options)) {
          ["A", "B", "C", "D"].forEach((k, idx) => {
            optionsObj[k].en = q.options[idx] || "";
          });
        }
        ["A", "B", "C", "D"].forEach(k => {
          const flatEn = q[`option ${k.toLowerCase()}`] || q[`option${k}`] || "";
          const flatTa = q[`option ${k.toLowerCase()} ta`] || q[`option${k}Ta`] || "";
          if (flatEn && !optionsObj[k].en) optionsObj[k].en = flatEn;
          if (flatTa && !optionsObj[k].ta) optionsObj[k].ta = flatTa;
        });
        let correctAnswer = q.correctAnswer || q.correctOption || q.answer || "";
        correctAnswer = correctAnswer.toString().trim().toUpperCase();
        if (!["A", "B", "C", "D"].includes(correctAnswer)) {
          correctAnswer = "A";
        }
        return {
          ...q,
          questionEn,
          questionTa,
          options: optionsObj,
          correctAnswer
        };
      });
      setExtractedQuestions(normalized);
      setExtractDraftId(data.draftId || "");
      Alert.alert("Extraction Complete!", `Extracted ${data.questionCount || 0} questions successfully.`);
    } catch (e: any) {
      if (abortCtrl.signal.aborted) return; // silently ignore cancelled
      Alert.alert("Extraction Failed", e.message || "Extraction failed.");
    } finally {
      extractionAbortRef.current = null;
      setIsExtracting(false);
    }
  };

  // Cancel ongoing extraction
  const cancelExtraction = () => {
    Alert.alert(
      "Cancel Extraction",
      "Are you sure you want to cancel the question extraction? Any progress will be lost.",
      [
        { text: "Keep Waiting", style: "cancel" },
        {
          text: "Cancel Extraction", style: "destructive",
          onPress: () => {
            if (extractionAbortRef.current) {
              extractionAbortRef.current.abort();
              extractionAbortRef.current = null;
            }
            setIsExtracting(false);
          }
        }
      ]
    );
  };

  // Upload & Attach Image to Extracted Question (uploads to Google Drive)
  const handleUploadQuestionImage = (qIdx: number) => {
    if (typeof document === "undefined") return;
    const fileInput = document.createElement("input");
    fileInput.type = "file";
    fileInput.accept = "image/*";
    fileInput.onchange = async (e: any) => {
      const file = e.target?.files?.[0];
      if (!file) return;
      try {
        // First compress locally (keeps bandwidth reasonable)
        const compressedBase64 = await compressFileImage(file, 1200, 1200, 0.85);

        // Try uploading to Google Drive via backend
        let finalImageUrl: string = compressedBase64;
        let uploadedToDrive = false;
        try {
          const driveRes = await api.current.post("/test-portal/test-creation/upload-question-image", {
            base64: compressedBase64,
            fileName: `q${qIdx + 1}_${file.name.replace(/[^a-zA-Z0-9._-]/g, "_")}`,
            testTitle: newPdfTest.title || "Test"
          });
          if (driveRes?.imageUrl) {
            finalImageUrl = driveRes.imageUrl;
            uploadedToDrive = true;
          }
        } catch (driveErr: any) {
          console.warn("[Drive] Question image upload failed, falling back to base64:", driveErr?.message);
        }

        // Update extractedQuestions and editingQData with the final URL (Drive URL or base64)
        setExtractedQuestions(prev => {
          const updated = [...prev];
          updated[qIdx] = { ...updated[qIdx], imageUrl: finalImageUrl };
          return updated;
        });
        if (editingQIdx === qIdx && editingQData) {
          setEditingQData((prev: any) => prev ? { ...prev, imageUrl: finalImageUrl } : null);
        }

        Alert.alert(
          "Image Attached!",
          uploadedToDrive
            ? `Image uploaded to Google Drive and attached to Question #${qIdx + 1}.`
            : `Image attached to Question #${qIdx + 1} (stored locally — Drive upload unavailable).`
        );
      } catch (err: any) {
        Alert.alert("Upload Error", err.message || "Could not read image file.");
      }
    };
    fileInput.click();
  };

  // Create Test from AI Extracted Questions
  const createTestFromExtraction = async () => {
    if ((genMode !== "json" && !extractDraftId) || !newPdfTest.title) {
      Alert.alert("Error", "Title and extracted questions are required.");
      return;
    }
    if (!newPdfTest.startTime || !newPdfTest.endTime) {
      Alert.alert("Error", "Scheduled Start Time and End Time are mandatory.");
      return;
    }
    try {
      const correctVal = parseFloat(newPdfTest.marksPerQ) || 1;
      const wrongVal = Math.abs(parseFloat(newPdfTest.negMarks) || 0.33);
      const unattendedVal = parseFloat(newPdfTest.unattendedMarks) || 0;

      await api.post("/test-portal/test-creation", {
        title: newPdfTest.title,
        draftId: genMode === "json" ? null : extractDraftId,
        questions: extractedQuestions, // Send edited questions array!
        startTime: newPdfTest.startTime || null,
        endTime: newPdfTest.endTime || null,
        marksPerQuestion: correctVal,
        negativeMarks: wrongVal,
        unattendedMarks: unattendedVal,
        totalMarks: extractedQuestions.length * correctVal,
        createdBy: user?.name || "admin",
        published: true,
        targetAudience: newPdfTest.targetAudience || "all",
        targetBatch: newPdfTest.targetAudience === "batch" ? newPdfTest.targetBatch || "" : "",
        requireFeedback: newPdfTest.requireFeedback,
        allowOfflineDirectly: !!newPdfTest.allowOfflineDirectly,
        testType: newPdfTest.testType || "mock",
        subject: newPdfTest.subject || "",
        topic: newPdfTest.topic || "",
        testMode: newPdfTest.testMode || "online"
      });
      if (newPdfTest.subject) {
        setKnownSubjects(prev => prev.includes(newPdfTest.subject) ? prev : [...prev, newPdfTest.subject]);
        if (newPdfTest.topic) {
          setKnownTopics(prev => ({ ...prev, [newPdfTest.subject]: [...new Set([...(prev[newPdfTest.subject] || []), newPdfTest.topic])] }));
        }
      }
      Alert.alert("Success", "Test created from extracted questions!");
      setExtractedQuestions([]);
      setExtractDraftId("");
      setPdfExtractText("");
      setPdfBase64("");
      setPdfFilename("");
      setAkBase64("");
      setAkFilename("");
      const start = new Date(Date.now() + 15 * 60 * 1000);
      const end = new Date(start.getTime() + 60 * 60 * 1000);
      const startStr = start.getFullYear() + "-" + String(start.getMonth() + 1).padStart(2, "0") + "-" + String(start.getDate()).padStart(2, "0") + "T" + String(start.getHours()).padStart(2, "0") + ":" + String(Math.floor(start.getMinutes() / 5) * 5).padStart(2, "0");
      const endStr = end.getFullYear() + "-" + String(end.getMonth() + 1).padStart(2, "0") + "-" + String(end.getDate()).padStart(2, "0") + "T" + String(end.getHours()).padStart(2, "0") + ":" + String(Math.floor(end.getMinutes() / 5) * 5).padStart(2, "0");
      setNewPdfTest({ title: "", startTime: startStr, endTime: endStr, marksPerQ: "", negMarks: "", unattendedMarks: "", totalMarks: "", targetAudience: "", targetBatch: "", requireFeedback: false, testType: "mock", subject: "", topic: "", testMode: "online", allowOfflineDirectly: false });
      setTestSub("available");
      loadTests();
    } catch (e: any) {
      Alert.alert("Error", e.message || "Failed to create test.");
    }
  };

