  // IST-Aware time parser: appends +05:30 if no timezone info so dates stored as "2026-08-04T12:40" are correctly parsed
  const parseTestTimeMs = (val: any): number => {
    if (!val) return 0;
    if (typeof val === "number") return val;
    if (typeof val === "object" && typeof val.toDate === "function") return val.toDate().getTime();
    if (typeof val === "object" && val._seconds) return val._seconds * 1000;
    const str = String(val);
    if (str.includes("T") && !str.endsWith("Z") && !/[+-]\d{2}:\d{2}$/.test(str)) {
      return new Date(str + "+05:30").getTime();
    }
    return new Date(str).getTime();
  };

  // Exam Operations
  const getTestStatusForStudent = (test: any) => {
    // Find if student has completed or started this test
    const attempt = studentAttempts.find((a: any) => a.testId === test.id);
    const now = Date.now();
    // Use IST-aware parsing to avoid timezone scheduling bugs
    const startTimeMs = test.startTime ? parseTestTimeMs(test.startTime) : 0;
    const endTimeMs = test.endTime ? parseTestTimeMs(test.endTime) : 0;

    if (attempt && (attempt.status === "submitted" || attempt.status === "evaluated" || attempt.isSubmitted)) {
      return { status: "completed", label: "Review Answers", attemptId: attempt.id || attempt.attemptId, disabled: false };
    }

    if (startTimeMs && now < startTimeMs) {
      return { status: "scheduled", label: "Scheduled", disabled: true };
    }

    if (endTimeMs && now > endTimeMs) {
      return { status: "expired", label: "Expired", disabled: true };
    }

    // Otherwise they can launch/resume the exam
    if (attempt && attempt.status === "started") {
      return { status: "ongoing", label: "Resume Exam", attemptId: attempt.id || attempt.attemptId, disabled: false };
    }

    return { status: "ready", label: "Start Test", disabled: false };
  };

  const launchReview = async (attemptId: string) => {
    setReviewLoading(true);
    try {
      const res = await api.get(`/test-portal/review/attempt/${attemptId}`);
      const reviewPayload = res?.data || res;

      // Normalize options from legacy object format {A:{en,ta}, B:...} → flat string array
      if (reviewPayload && Array.isArray(reviewPayload.questions)) {
        reviewPayload.questions = reviewPayload.questions.map((q: any) => {
          let options: string[] = [];
          let optionsTa: string[] = [];

          if (Array.isArray(q.options)) {
            options = q.options.map((o: any) => typeof o === "string" ? o : (o?.en || ""));
          } else if (q.options && typeof q.options === "object") {
            options = [
              q.options.A?.en || q.options.A || "",
              q.options.B?.en || q.options.B || "",
              q.options.C?.en || q.options.C || "",
              q.options.D?.en || q.options.D || ""
            ];
          }

          if (Array.isArray(q.optionsTa)) {
            optionsTa = q.optionsTa.map((o: any) => typeof o === "string" ? o : (o?.ta || ""));
          } else if (q.options && typeof q.options === "object") {
            optionsTa = [
              q.options.A?.ta || "",
              q.options.B?.ta || "",
              q.options.C?.ta || "",
              q.options.D?.ta || ""
            ];
          }

          while (options.length < 4) options.push("");
          while (optionsTa.length < 4) optionsTa.push("");

          return { ...q, options, optionsTa };
        });
      }

      setReviewData(reviewPayload);
      setReviewMode(true);
    } catch (e: any) {
      Alert.alert("Error Fetching Review", e.message || "Could not load test review details.");
    } finally {
      setReviewLoading(false);
    }
  };

