                          <Text style={{ color: devActiveCollection === col.name ? (darkMode ? "#ef9a9a" : "#c62828") : (darkMode ? "#e0e0e0" : "#212121"), fontSize: 12, fontWeight: "bold", flex: 1 }} numberOfLines={1}>{col.name}</Text>
