                      const rawCount = myStudent?.profileSubmitCount;
                      const submitCount = typeof rawCount === "number" ? rawCount : (rawCount && typeof rawCount === "object" && typeof (rawCount as any).__increment === "number") ? (rawCount as any).__increment : 0;
